const L = require('lv-automation').w39;
const j = $input.first().json;
const c = L.resolveCaller(j.headers || {}, $env, Date.now());
return [{ json: c.ok ? { ok: true, lead_id: c.lead_id } : { ok: false, status: c.status, body: c.body, reason: c.reason } }];

const L = require('lv-automation').w39;
const r = $input.first().json;
const g = L.leadGate(r.lead);
if (!g.ok) return [{ json: { status: g.status, body: g.body, reason: g.reason } }];
return [{ json: L.startView({ lead: r.lead, broker: r.broker, booking: r.booking }) }];

const L = require('lv-automation').w39;
const j = $input.first().json;
const c = L.resolveCaller(j.headers || {}, $env, Date.now());
if (!c.ok) return [{ json: { ok: false, status: c.status, body: c.body, reason: c.reason } }];
const p = L.parseAnswers(j.body);
if (!p.ok) return [{ json: { ok: false, status: p.status, body: p.body, reason: p.reason } }];
return [{ json: { ok: true, lead_id: c.lead_id, answers: p.answers, request_id: p.request_id, confirm_adviser: p.confirm_adviser, key: L.answersKey(c.lead_id, p.request_id, !!p.confirm_adviser) } }];

