SELECT (SELECT to_jsonb(x) FROM (SELECT l.id, l.brand_id, l.broker_id, l.origin, l.routing_reason, l.first_name, l.phone, l.opted_out_at, (l.phone IS NULL) AS erased, l.stage, l.conv_state,
         l.age_band, l.budget_band, l.product_interest, l.disqualified_reason FROM public.leads l WHERE l.id::text = $1 AND l.brand_id IS NOT NULL) x) AS lead,
       (SELECT a.payload FROM public.lead_activities a WHERE a.idempotency_key = $2 LIMIT 1) AS prior;

